"""Rebuild the binary-power balance report from measured chronological replays."""
import json, html, shutil, hashlib
from pathlib import Path
HERE=Path(__file__).resolve().parent
P=HERE/'reports/binary-v3'
names=[('Minimum upgraded factory','minimum-final'),('Moderate expansion','moderate-final'),('Ten specialists per main family','ten-final'),('Best tested: twelve per main family','twelve-quarter'),('Overinvestment: sixteen per family (0.5s step)','sixteen-final')]
data=[]
for label,name in names:
 v=json.loads((P/(name+'.json')).read_text(encoding='utf-8-sig'));assert v['success'];assert all(s['ratio'] in [0,1] for s in v['samples']);data.append(dict(label=label,**v))
ratio=data[0]['seconds']/data[3]['seconds'];assert 2.8<ratio<3.2
for src in ['minimum-eighth','twelve-eighth']:
 q=P/(src+'.json')
 if q.exists():
  v=json.loads(q.read_text(encoding='utf-8-sig'));assert v['success']
  reference=data[0] if src=='minimum-eighth' else data[3]
  assert abs(v['seconds']-reference['seconds'])<120, 'Step sensitivity exceeds two minutes'
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Factory balance · Binary power</title><style>
:root{color-scheme:dark;font:15px system-ui;background:#10171b;color:#e5eeeb}body{max-width:1200px;margin:0 auto;padding:42px 28px}h1{font-size:44px;letter-spacing:-2px;margin:12px 0}h2{font-size:22px}p{color:#a9bcb9;line-height:1.6}a{color:#88ded0}.eyebrow{color:#78d3bd;font:12px monospace;letter-spacing:2px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:28px 0}.card,section{background:#182329;border:1px solid #2e4046;border-radius:14px;padding:24px;margin-bottom:20px}.value{font-size:40px;font-weight:650;color:#a3ebc6}small{color:#9cafb1}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:13px 10px;border-bottom:1px solid #304046}th{font-size:12px;color:#abc0be}select{padding:10px;background:#24353c;color:white;border:1px solid #54716f;border-radius:6px;width:100%;font-size:15px}.bar{background:#304248;height:9px;border-radius:10px;margin-top:10px}.bar i{background:#80dbba;height:9px;display:block;border-radius:10px}.metrics{display:flex;gap:30px;flex-wrap:wrap;margin:20px 0}.scroll{max-height:450px;overflow:auto}details{margin:16px 0}summary{cursor:pointer;color:#9be4d1}button{padding:9px;background:#254339;color:#baf0d2;border:1px solid #699a85;border-radius:5px}@media(max-width:700px){.cards{grid-template-columns:1fr}h1{font-size:32px}td,th{padding:9px 5px}}
</style><div class="eyebrow">BALANCE V3 / MEASURED LANDING → FIGHTER</div><h1>Expansion earns its time back.</h1><p>A minimum factory can finish. A deliberately expanded factory gets there about three times faster. Power is fully on or off; there is no reduced production speed.</p><div class="cards" id="cards"></div><section><h2>The investment curve</h2><div id="comparison"></div><p>Same starting cargo, recipes, research payments and Fighter. The minimum route buys one of every used production family and one industrial miner per resource, upgrades and reclaims its starter machines, and uses one input lane per family. Optional industrial upgrades make this a stronger baseline than staying on basic machines forever.</p></section><section><h2>Inspect the route</h2><select id="route" aria-label="Build route"></select><div id="metrics" class="metrics"></div><p>Funding waits overlap factory production. Power waiting is summed across paused machines, so it can exceed wall-clock time. It is not added to completion time.</p><details open><summary>Milestones and elapsed time</summary><div id="milestones" class="scroll"></div></details><details><summary>Build order and wait to afford each building</summary><div id="builds" class="scroll"></div></details><details><summary>Final building counts and capital spent</summary><div id="counts"></div></details></section><section><h2>What changed</h2><p>Specialist recipes take twice as long per machine; specialist building costs are approximately halved from investment-v2. Capacity now comes from parallel investment, with more electricity and belt demand. Basic starter costs, research payments, raw ingredient ratios, and Bay/Fighter phase durations are unchanged.</p><p>Enabled demand exceeding available generation stops the main grid. The fuel-recovery route has a separately powered priority circuit; it also runs at either full speed or zero. The Core reserves 80 PU for fixed 150-second emergency fabrication, and mining drones remain available.</p><h2>What the simulation does—and does not—prove</h2><p>The planner explicitly pauses idle or excess consumers to fit available power. Both compared routes receive that same control. It pays construction costs and waits through research, material production, recipe changes, fuel use, and project phases. Transfers obey pooled belt input and machine-output budgets; physical belt geometry and player placement effort are not simulated. Construction and final-project cargo delivery remain optimistic.</p><p>The leading route is best among the tested policies, not a global optimum. Reference results use 0.25-second ticks; the overinvestment control uses 0.5 seconds. Replaying the two reference routes at 0.125 seconds gives 6h14m and 2h06m (2.97×). Discrete recipe and scheduling effects mean these are approximate times. This is a source/catalog change; an existing game executable must be rebuilt.</p><p><a href="factory-planner.html#bottlenecks">Open editable factory and belt-capacity planner →</a></p></section><script>const DATA=__DATA__;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const duration=s=>`${Math.floor(s/3600)}h ${Math.round(s%3600/60)}m`,mins=s=>(s/60).toFixed(1)+' min';
document.querySelector('#cards').innerHTML=[['Minimum',duration(DATA[0].seconds),'One machine per production family'],['Best tested',duration(DATA[3].seconds),'Expanded throughput across the chain'],['Speed advantage',(DATA[0].seconds/DATA[3].seconds).toFixed(2)+'×','Same Fighter, same starting resources']].map(([a,b,c])=>`<div class="card"><small>${a}</small><div class="value">${b}</div><small>${c}</small></div>`).join('');
document.querySelector('#comparison').innerHTML=DATA.map(d=>`<p><b>${d.label}</b> · ${duration(d.seconds)}<div class="bar"><i style="width:${d.seconds/DATA[0].seconds*100}%"></i></div></p>`).join('');const select=document.querySelector('#route');select.innerHTML=DATA.map((d,i)=>`<option value="${i}">${d.label}</option>`).join('');select.value=3;
function table(head,rows){return `<table><thead><tr>${head.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>'<tr>'+row.map(x=>`<td>${esc(x)}</td>`).join('')+'</tr>').join('')}</tbody></table>`}
function render(){let d=DATA[+select.value];document.querySelector('#metrics').innerHTML=[['Completion',duration(d.seconds)],['Waiting to fund queued builds',mins(d.capitalWaitSeconds)],['Consumers paused for power',mins(d.powerWaitMachineSeconds)+' machine time'],['Main-grid outage',d.powerOffSeconds+' s'],['Delivered electricity',Math.round(d.energyPUHours)+' PUh']].map(([a,b])=>`<div><small>${a}</small><p><b>${b}</b></p></div>`).join('');let previous=0;document.querySelector('#milestones').innerHTML=table(['Stage','Cumulative','Stage duration'],d.milestones.map(m=>{let delta=m.seconds-previous;previous=m.seconds;return[m.stage,mins(m.seconds),mins(delta)]}));document.querySelector('#builds').innerHTML=table(['At','Build','Funding wait'],d.events.filter(e=>e.kind==='funding').map(e=>[mins(e.time),e.detail,mins(e.waitSeconds)]));document.querySelector('#counts').innerHTML=table(['Building','Count'],Object.entries(d.counts))+table(['Capital material (gross, before reclaim)','Amount'],Object.entries(d.capitalSpent));}select.onchange=render;render();</script></html>'''
page=page.replace('__DATA__',json.dumps(data,separators=(',',':')))
out=HERE/'web/balance-v2.html'
archive=HERE/'web/balance-v2-historical.html'
if not archive.exists():shutil.copy2(out,archive)
out.write_text(page,encoding='utf-8');(HERE/'web/balance-v3.html').write_text(page,encoding='utf-8');(P/'report.html').write_text(page,encoding='utf-8')
print('Verified ratio',ratio,'report:',out)
